#include "source.hpp"
int main(int argc,char**argv){try{ff::init();std::cout<<"K_field_size "<<ff::N<<" primitive_generator_code "<<ff::generator<<"\n";init_source();std::string mode=argc>1?argv[1]:"build";if(mode=="build"){auto s=make_affine(std::cout);write_affine(argc>2?argv[2]:"inputs/source_affine.dat",s);return 0;}auto basis=read_affine(argc>2?argv[2]:"inputs/source_affine.dat");F detc=0;int tested=0;for(F w:{2,3,5,6,25,26,51})for(F h:{1,2,5,31}){Chart ch=chart(basis,h,w);F H=ff::mul(h,w),q=ff::pow(w,3),expected=ff::div(psieval(H,q),ff::mul(q,ff::pow(299619,2)));if(ch.F6!=expected)throw std::runtime_error("F6 formula mismatch");F dc=ff::div(ch.det,ff::mul(w,w));if(detc&&dc!=detc)throw std::runtime_error("det/w2 not constant");detc=dc;auto con=constraints(ch.s,true);for(auto v:con)if(v)throw std::runtime_error("reconstructed constraint mismatch");if(!allowed(H,q,1))continue;auto D=compactD(ch.s);for(F mu:{1,2,5}){F la=ff::mul(w,mu);auto R=residual(D,la);F lead=ff::pow(ff::mul(ff::mul(3,ff::pow(h,3)),ff::mul(ff::pow(epsilon,8),ch.F6)),3);if(R.deg()!=140||R.v.back()!=lead)throw std::runtime_error("residual degree/lead mismatch");int failure=first_square_failure(R);std::cout<<"sample h="<<h<<" w="<<w<<" H="<<H<<" q="<<q<<" mu="<<mu<<" degree="<<R.deg()<<" first_square_failure="<<failure<<"\n";tested++;if(failure<0)throw std::runtime_error("SQUARE CANDIDATE FOUND -- preserve and verify");}}
std::cout<<"checked_samples "<<tested<<" det_over_w2 "<<detc<<" PASS\n";
}catch(const std::exception&e){std::cerr<<"ERROR "<<e.what()<<"\n";return 1;}return 0;}
